const require_index = require("../useEvent/index.js");
let react = require("react");
//#region src/useBoolean/index.ts
const useBoolean = (initialValue = false) => {
	const [value, setValue] = (0, react.useState)(initialValue);
	const setTrue = require_index.useEvent(() => {
		setValue(true);
	});
	const setFalse = require_index.useEvent(() => {
		setValue(false);
	});
	const toggle = require_index.useEvent(() => {
		setValue((prev) => !prev);
	});
	return {
		value,
		setValue: require_index.useEvent((newValue) => {
			setValue(newValue);
		}),
		setTrue,
		setFalse,
		toggle
	};
};
//#endregion
exports.useBoolean = useBoolean;
